package dev.mando;
import io.papermc.paper.dialog.Dialog;import io.papermc.paper.registry.data.dialog.DialogBase;import io.papermc.paper.registry.data.dialog.body.DialogBody;import io.papermc.paper.registry.data.dialog.type.DialogType;import net.kyori.adventure.text.Component;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class ChangelogCommand implements CommandExecutor{
 private final MandoPlugin plugin;public ChangelogCommand(MandoPlugin p){plugin=p;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage(plugin.msg("only-players"));return true;}String version=plugin.getPluginMeta().getVersion(),date=plugin.getConfig().getString("changelog.date","2026-10-02");List<String> lines=plugin.getConfig().getStringList("changelog.lines");StringBuilder body=new StringBuilder(date+" · Mando "+version+"\n\nCAMBIOS DE ESTA BUILD\n");for(String line:lines)body.append("• ").append(line).append("\n");body.append("\nEstado: integración en desarrollo. Esta versión no se marca como leída al abrirla.");p.showDialog(Dialog.create(b->b.empty().base(DialogBase.builder(Component.text("Novedades de Mando")).body(List.of(DialogBody.plainMessage(Component.text(body.toString())))).build()).type(DialogType.notice())));return true;}
}